NODES_QUERY:
query($ids: [ID!]!) {
  viewer { login }
  nodes(ids: $ids) {
    ... on Issue {

  __typename id number title url state createdAt closedAt bodyText authorAssociation
  author { __typename login }
  repository { nameWithOwner }
  milestone { title }
  assignees(first: 10) { nodes { login } }
  comments(last: 20) { pageInfo { hasPreviousPage } nodes { databaseId createdAt bodyText url authorAssociation author { __typename login } } }

      timelineItems(last: 30, itemTypes: [ASSIGNED_EVENT, UNASSIGNED_EVENT]) { pageInfo { hasPreviousPage } nodes { 
  ... on AssignedEvent { __typename id createdAt actor { __typename login } assignee { ... on User { login } } }
  ... on UnassignedEvent { __typename id createdAt actor { __typename login } assignee { ... on User { login } } }
 } }
    }
    ... on PullRequest {

  __typename id number title url state createdAt closedAt bodyText authorAssociation
  author { __typename login }
  repository { nameWithOwner }
  milestone { title }
  assignees(first: 10) { nodes { login } }
  comments(last: 20) { pageInfo { hasPreviousPage } nodes { databaseId createdAt bodyText url authorAssociation author { __typename login } } }

      isDraft mergedAt headRefOid reviewDecision
      mergedBy { __typename login }
      reviewRequests(first: 20) { nodes { requestedReviewer { ... on User { login } ... on Team { slug } } } }
      reviews(last: 10) { pageInfo { hasPreviousPage } nodes { databaseId state submittedAt bodyText url authorAssociation author { __typename login } } }
      reviewThreads(last: 10) { pageInfo { hasPreviousPage } nodes { comments(last: 5) { pageInfo { hasPreviousPage } nodes { databaseId createdAt bodyText url authorAssociation author { __typename login } } } } }
      commits(last: 1) { nodes { commit { statusCheckRollup { state contexts(first: 50) { nodes {
        __typename
        ... on CheckRun { conclusion completedAt }
        ... on StatusContext { state createdAt }
      } } } } } }
      timelineItems(last: 30, itemTypes: [ASSIGNED_EVENT, UNASSIGNED_EVENT, REVIEW_REQUESTED_EVENT, REVIEW_REQUEST_REMOVED_EVENT]) {
        pageInfo { hasPreviousPage }
        nodes {

  ... on AssignedEvent { __typename id createdAt actor { __typename login } assignee { ... on User { login } } }
  ... on UnassignedEvent { __typename id createdAt actor { __typename login } assignee { ... on User { login } } }

          ... on ReviewRequestedEvent { __typename id createdAt actor { __typename login } requestedReviewer { ... on User { login } ... on Team { slug } } }
          ... on ReviewRequestRemovedEvent { __typename id createdAt actor { __typename login } requestedReviewer { ... on User { login } ... on Team { slug } } }
        }
      }
    }
  }
}

